from typing import List, Optional

@dataclass
class FileNode:
    name: str
    children: List['FileNode'] = field(default_factory=list)

@dataclass
class FileSystemTree:
    root: FileNode

    def find_node(self, path: List[str]) -> Optional[FileNode]:
        current_node = self.root
        for part in path:
            for child in current_node.children:
                if child.name == part:
                    current_node = child
                    break
            else:
                return None
        return current_node

